@php $visible = $limit ?? $queue->count(); @endphp
<div class="card queue-card"><div class="card-title between"><span><svg width="16" height="16"><use href="#ico-list"/></svg> Content queue</span>@if($showAll ?? false)<button class="btn-sm" data-page="queue">View all</button>@endif</div>
@forelse($queue->take($visible) as $post)
	@php $statusLabel = ['pending_ai' => 'AI queued', 'pending_review' => 'Needs review', 'approved' => 'Approved', 'publishing' => 'Publishing', 'published' => 'Published', 'failed' => 'Failed'][$post->status] ?? ucfirst($post->status); $badge = in_array($post->status, ['pending_review', 'failed']) ? 'review' : (in_array($post->status, ['pending_ai', 'publishing']) ? 'generating' : 'scheduled'); @endphp
	<div class="queue-item"><div class="thumb"></div><div class="qi-info"><div class="title">{{ $post->title }}</div><div class="meta"><span class="queue-platform-icons" aria-label="Social platforms">@foreach($post->platforms as $platform)<svg width="14" height="14"><use href="#ico-{{ $platform }}"/></svg>@endforeach</span><span class="status-badge badge-{{ $badge }}">{{ $statusLabel }}</span></div></div><div class="qi-actions">@if($post->status === 'pending_review')<button class="btn-sm" data-action="review" data-content-id="{{ $post->id }}" data-title="{{ $post->title }}" data-caption="{{ $post->edited_caption ?: $post->generated_caption }}" data-hashtags="{{ implode(' ', $post->generated_hashtags ?: []) }}"><svg width="13" height="13"><use href="#ico-edit"/></svg> Review</button><form method="POST" action="{{ route('content.approve', $post) }}">@csrf<button class="btn-sm primary" type="submit">Publish</button></form>@elseif($post->status === 'failed')<button class="btn-sm" data-action="review" data-content-id="{{ $post->id }}" data-title="{{ $post->title }}" data-caption="{{ $post->edited_caption ?: $post->generated_caption }}" data-hashtags="{{ implode(' ', $post->generated_hashtags ?: []) }}">Retry review</button>@endif</div></div>
@empty
	<div class="queue-item"><div class="qi-info"><div class="title">No content yet</div><div class="meta">Upload media to start the workflow.</div></div></div>
@endforelse</div>
